sys_rte_eb_script_operation.script:
(function(batch, output) {
   for (var i = 0; i < batch.length; i++) {
      var input = batch[i].input; // Value of the input column.
      output[i] = '';
      new global.GlideQuery('cmn_department')
      .where('id', input)
      .select(['id', "u_active"])
      .forEach(function(dep) {
         // Associar o departamento mesmo que não esteja ativo
         if(! output[i]){
             output[i] = dep.sys_id;
         } else {
            if(dep.u_active) {
             output[i] = dep.sys_id;
            }
         }
      });
   }
})(batch, output);
